    constexpr int V_STRIDE = 64;
    constexpr int O_STRIDE = 64;
    extern __shared__ char smem_raw[];
    const int SS = S + 4;
    const int PS = S;
    const size_t scores_bytes = (size_t)MROWS * SS * sizeof(float);
    float*  scores = reinterpret_cast<float*>(smem_raw);
    __half* q_s0 = reinterpret_cast<__half*>(smem_raw + scores_bytes);
    __half* q_s1 = q_s0 + (size_t)MROWS * QK_STRIDE;
    __half* k_s0 = q_s1 + (size_t)MROWS * QK_STRIDE;
    __half* k_s1 = k_s0 + (size_t)S * QK_STRIDE;
    __half* v_s0 = reinterpret_cast<__half*>(smem_raw);
    __half* v_s1 = reinterpret_cast<__half*>(smem_raw + scores_bytes);
    float*  o_s = reinterpret_cast<float*>(v_s1 + (size_t)S * V_STRIDE);
    __half* p_s = reinterpret_cast<__half*>(o_s + (size_t)MROWS * O_STRIDE);
