    const int q0 = blockIdx.x * MROWS;
    const long base = (long)bh * (long)S * (long)D;
    const __half* Qg = Q + base;
    const __half* Kg = K + base;
    const __half* Vg = V + base;
    __half* Og = O + base;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int warp_m = warp & 1;
    const int warp_n = warp >> 1;
    // Phase 1: scores = Q_tile @ K^T (tensor cores, fp32 accumulation),
    // with 2-stage cp.async pipelining of the Q/K tiles.
    auto load_qk = [&](int kc, __half* qb, __half* kb) {
        for (int idx = tid; idx < MROWS * 4; idx += 256) {
            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(qb + r * QK_STRIDE + c8,
                                    Qg + (long)(q0 + r) * D + kc + c8, 16);
        }
        for (int idx = tid; idx < S * 4; idx += 256) {
            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(kb + r * QK_STRIDE + c8,
                                    Kg + (long)r * D + kc + c8, 16);
        }
        __pipeline_commit();
    };
    auto load_v = [&](int nc, __half* vb) {
        for (int idx = tid; idx < S * 8; idx += 256) {
            const int r = idx >> 3;
            const int c8 = (idx & 7) << 3;
            __pipeline_memcpy_async(vb + r * V_STRIDE + c8,
                                    Vg + (long)r * D + nc + c8, 16);
        }
        __pipeline_commit();
    };
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[NT];
    #pragma unroll
    for (int t = 0; t < NT; ++t) wmma::fill_fragment(acc[t], 0.0f);
    load_qk(0, q_s0, k_s0);
    int buf = 0;
    for (int kc = 0; kc < D; kc += 32) {
        const int nkc = kc + 32;
        __half* qb = buf ? q_s1 : q_s0;
        __half* kb = buf ? k_s1 : k_s0;
        if (nkc < D) load_qk(nkc, buf ? q_s0 : q_s1, buf ? k_s0 : k_s1);
        __pipeline_wait_prior(nkc < D ? 1 : 0);
        __syncthreads();
