            wmma::load_matrix_sync(a, qb + (warp_m * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
            #pragma unroll
            for (int t = 0; t < NT; ++t) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> b;
                wmma::load_matrix_sync(b, kb + (warp_n * (NT * 16) + t * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
                wmma::mma_sync(acc[t], a, b, acc[t]);
            }
        }
        __syncthreads();
        buf ^= 1;
    }
