    for (int nc = 0; nc < D; nc += 64) {
        const int nnc = nc + 64;
        __half* vb = vbuf ? v_s1 : v_s0;
        if (nnc < D) load_v(nnc, vbuf ? v_s0 : v_s1);
        __pipeline_wait_prior(nnc < D ? 1 : 0);
        __syncthreads();
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc;
        wmma::fill_fragment(oacc, 0.0f);
        #pragma unroll
        for (int kf = 0; kf < KFRAGS; ++kf) {
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b;
            wmma::load_matrix_sync(b, vb + (kf * 16) * V_STRIDE + warp_n * 16, V_STRIDE);
            wmma::mma_sync(oacc, pfrag[kf], b, oacc);
        }
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 16,
                                oacc, O_STRIDE, wmma::mem_row_major);
        __syncthreads();
        for (int idx = tid; idx < MROWS * 32; idx += 256) {
            const int r = idx >> 5;
            const int c2 = (idx & 31) << 1;
            __half2 hv;
            hv.x = __float2half(o_s[r * O_STRIDE + c2]);
            hv.y = __float2half(o_s[r * O_STRIDE + c2 + 1]);
            *reinterpret_cast<__half2*>(Og + (long)(q0 + r) * D + nc + c2) = hv;
        }
        __syncthreads();
        vbuf ^= 1;
    }
}
template <int NT>
static void sdpa_launch(const __half* q, const __half* k, const __half* v, __half* o,
                        int S, int D, float scale, dim3 grid, size_t smem, cudaStream_t stream) {
    static bool configured = false;
