    const __half* q = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* k = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* v = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* o = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / 64) {
        case 1: sdpa_launch<1>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 2: sdpa_launch<2>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 3: sdpa_launch<3>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 4: sdpa_launch<4>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        default: TORCH_CHECK(false, "unsupported sequence length");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return O;
}
